import json
import csv
import pandas as pd

FIELD_MAPPINGS = {
    'user_id': ['user_id', 'id', 'userId'],
    'name': ['full_name', 'name', 'userName'],
    'email': ['email', 'email_address'],
    'created_date': ['registration_date', 'created_at', 'joined'],
    'status': ['status', 'is_active', 'active'],
}

def normalize_record(record):
    normalized = {}
    for unified_field, possible_names in FIELD_MAPPINGS.items():
        for field_name in possible_names:
            if field_name in record:
                value = record[field_name]
                if unified_field == 'user_id':
                    value = int(value)
                elif unified_field == 'created_date':
                    value = str(value)[:10]
                normalized[unified_field] = value
                break
    return normalized

# Load source_a
with open('/data/source_a/users.json') as f:
    source_a_data = json.load(f)
source_a = {r['id']: normalize_record(r) for r in source_a_data}

# Load source_b
source_b = {}
with open('/data/source_b/users.csv') as f:
    for row in csv.DictReader(f):
        rec = normalize_record(row)
        source_b[rec['user_id']] = rec

# Load source_c
source_c = {}
for _, row in pd.read_parquet('/data/source_c/users.parquet').iterrows():
    rec = normalize_record(row.to_dict())
    source_c[rec['user_id']] = rec

all_user_ids = sorted(set(source_a) | set(source_b) | set(source_c))

conflicts = []
merged_records = []

for user_id in all_user_ids:
    sources = {
        'source_a': source_a.get(user_id),
        'source_b': source_b.get(user_id),
        'source_c': source_c.get(user_id),
    }

    all_fields = set()
    for src_data in sources.values():
        if src_data:
            all_fields.update(src_data.keys())

    merged = {}
    for field in sorted(all_fields):
        if field == 'user_id':
            merged[field] = user_id
            continue

        values = {
            src: src_data[field]
            for src, src_data in sources.items()
            if src_data and field in src_data
        }

        if len(set(str(v) for v in values.values())) > 1:
            if 'source_a' in values:
                selected = values['source_a']
            elif 'source_b' in values:
                selected = values['source_b']
            else:
                selected = values['source_c']

            conflicts.append({
                'user_id': user_id,
                'field': field,
                'values': values,
                'selected': selected,
            })
        else:
            selected = next(iter(values.values()))

        merged[field] = selected

    merged_records.append(merged)

# Build output DataFrame with required columns
df = pd.DataFrame(merged_records)
df['user_id'] = df['user_id'].astype(int)
df['name'] = df['name'].astype(str)
df['email'] = df['email'].astype(str)
df['created_date'] = df['created_date'].astype(str)

cols = ['user_id', 'name', 'email', 'created_date']
if 'status' in df.columns:
    df['status'] = df['status'].astype(str)
    cols.append('status')

df[cols].to_parquet('/app/merged_users.parquet', index=False)

with open('/app/conflicts.json', 'w') as f:
    json.dump({'total_conflicts': len(conflicts), 'conflicts': conflicts}, f, indent=2, default=str)

print(f"Users merged: {len(merged_records)}")
print(f"Conflicts found: {len(conflicts)}")
print()
print(df[cols].to_string())
print()
print("Conflicts:")
for c in conflicts:
    print(f"  user {c['user_id']} / {c['field']}: {c['values']} -> {c['selected']!r}")

